const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    // Define a polygon around the summit of Mount Stanley, Uganda
    const mountStanley = ee.Geometry.Polygon([[
        [29.852, 0.410],
        [29.900, 0.410],
        [29.900, 0.350],
        [29.852, 0.350],
        [29.852, 0.410]
    ]]);

    // Define the two time periods for comparison, focusing on the drier season (Jun-Aug)
    const startDate2020 = '2020-06-01';
    const endDate2020 = '2020-08-31';
    const startDate2024 = '2024-06-01';
    const endDate2024 = '2024-08-31';

    // 2. Data Acquisition & Processing Function
    // Function to mask clouds using the Sentinel-2 Scene Classification Layer (SCL)
    const cloudMask = function(image) {
        const scl = image.select('SCL');
        // Keep pixels classified as vegetation, bare soils, water, snow/ice, and unclassified.
        // SCL values: 4, 5, 6, 11, 7
        const mask = scl.eq(4).or(scl.eq(5)).or(scl.eq(6)).or(scl.eq(11)).or(scl.eq(7));
        return image.updateMask(mask);
    };

    // Function to get a clear composite and calculate snow/ice area
    const getSnowIceArea = function(startDate, endDate, aoi, collectionName) {
        let collection = ee.ImageCollection(collectionName)
            .filterBounds(aoi)
            .filterDate(startDate, endDate);

        if (collection.size().getInfo() === 0) {
            return {
                imageCount: 0,
                snowIceArea: null,
                validPixels: 0
            };
        }

        const maskedCollection = collection.map(cloudMask);
        const composite = maskedCollection.median(); // Median composite to reduce noise

        // Identify snow/ice using the SCL band (value 11)
        const snowIce = composite.select('SCL').eq(11);
        const snowIceMasked = snowIce.updateMask(snowIce); // Mask so only snow pixels are 1

        const areaImage = snowIceMasked.multiply(ee.Image.pixelArea());
        const scale = 30; // Use a moderate scale to avoid timeout

        // Count total valid (cloud-free) pixels in the composite
        const pixelCount = composite.select('B2').reduceRegion({
            reducer: ee.Reducer.count(),
            geometry: aoi,
            scale: scale,
            maxPixels: 1e9
        }).get('B2').getInfo();

        if (pixelCount === 0) {
            return {
                imageCount: collection.size().getInfo(),
                snowIceArea: null,
                validPixels: 0
            };
        }

        const snowIceArea = areaImage.reduceRegion({
            reducer: ee.Reducer.sum(),
            geometry: aoi,
            scale: scale,
            maxPixels: 1e9
        }).get('SCL');

        return {
            imageCount: collection.size().getInfo(),
            snowIceArea: ee.Number(snowIceArea).getInfo(),
            validPixels: pixelCount
        };
    };

    // 3. Calculation
    let result2020 = getSnowIceArea(startDate2020, endDate2020, mountStanley, 'COPERNICUS/S2_SR');
    if (result2020.imageCount === 0) {
        // Fallback to Landsat 8 if Sentinel-2 has no images
        console.log("No S2 images for 2020, trying Landsat 8...");
        result2020 = getSnowIceArea(startDate2020, endDate2020, mountStanley, 'LANDSAT/LC08/C02/T1_L2');
    }

    let result2024 = getSnowIceArea(startDate2024, endDate2024, mountStanley, 'COPERNICUS/S2_SR');

    // 4. Validation & Final Answer
    const area2020 = result2020.snowIceArea;
    const area2024 = result2024.snowIceArea;

    console.log(`2020 Info: Images found: ${result2020.imageCount}, Valid pixels: ${result2020.validPixels}`);
    console.log(`2024 Info: Images found: ${result2024.imageCount}, Valid pixels: ${result2024.validPixels}`);

    if (result2020.imageCount === 0 || result2024.imageCount === 0) {
        console.log("Evidence: No images found for one or both periods.");
        console.log("A: No");
        return;
    }

    if (result2020.validPixels === 0 || result2024.validPixels === 0) {
        console.log("Evidence: Could not create a cloud-free composite for one or both periods.");
        console.log("B: No");
        return;
    }

    if (area2020 === null || area2024 === null) {
        console.log("Evidence: Calculation failed. Snow/ice area could not be determined.");
        console.log("C3: Calculation Failure");
        return;
    }

    const area_km2_2020 = area2020 / 1e6;
    const area_km2_2024 = area2024 / 1e6;

    console.log(`2020 Glacial/Snow Area: ${area_km2_2020.toFixed(3)} km^2`);
    console.log(`2024 Glacial/Snow Area: ${area_km2_2024.toFixed(3)} km^2`);

    const change = area_km2_2024 - area_km2_2020;
    console.log(`Change in area: ${change.toFixed(3)} km^2`);

    if (area_km2_2024 < area_km2_2020) {
        console.log("Evidence: The calculated glacial and snow cover area was smaller in 2024 than in 2020.");
        console.log("A: Yes");
    } else {
        console.log("Evidence: The calculated glacial and snow cover area did not decrease from 2020 to 2024.");
        console.log("B: No");
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, (err) => {
                console.error('Authentication error:', err);
                reject(err);
            });
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, (err) => {
                console.error('Initialization error:', err);
                reject(err);
            });
        });
        await runAnalysis();
    } catch (e) {
        console.error('An error occurred during the analysis:', e);
        console.log("D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.");
    }
}

initEE();
